/* Frost Bakery module styles */
.root {
  /* Vitrina spine roles */
  --vt-surface: #F4F1DE;
  --vt-surface-2: #FFFFFF;
  --vt-surface-deep: #E8E3C8;
  --vt-ink: #3D405B;
  --vt-ink-soft: #575A78;
  --vt-on-deep: #F4F1DE;
  --vt-accent: #C45A3A; /* darkened terracotta for contrast */
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #C45A3A;
  --vt-accent-on-deep: #F0A58E;
  --vt-line: rgba(61, 64, 91, 0.1);

  /* Extended palette (derived from original) */
  --terracotta-light: #f0a58e;
  --terracotta-dark: #c4603f;
  --cream-dark: #e8e3c8;
  --navy-light: #575a78;
  --sage: #81B29A;
  --sage-light: #a8cfba;
  --sage-dark: #5f8e73;

  /* Typography */
  --font-heading: 'Lora', Georgia, serif;
  --font-body: 'Manrope', 'Segoe UI', sans-serif;

  /* Spacing */
  --sidebar-width: 260px;
  --section-pad: clamp(3rem, 6vw, 6rem);
  --gap: clamp(1rem, 2.5vw, 2rem);

  /* Borders & Radius */
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 24px;
  --radius-xl: 32px;

  /* Shadows */
  --shadow-card: 0 4px 24px rgba(61, 64, 91, 0.08);
  --shadow-hover: 0 8px 40px rgba(61, 64, 91, 0.14);

  /* Transitions */
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --duration: 0.5s;

  font-family: var(--font-body);
  color: var(--vt-ink);
  background-color: var(--vt-surface);
  line-height: 1.7;
  overflow-x: hidden;
}

.root *,
.root *::before,
.root *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  font-family: var(--font-heading);
  font-weight: 600;
  line-height: 1.2;
}

.root a {
  color: inherit;
  text-decoration: none;
}

.root ul {
  list-style: none;
}

/* Hidden checkbox for mobile nav */
.navToggle {
  display: none;
}

/* Hamburger */
.hamburger {
  display: none;
  position: fixed;
  top: 1rem;
  left: 1rem;
  z-index: 1100;
  width: 48px;
  height: 48px;
  background: var(--vt-ink);
  border-radius: var(--radius-sm);
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-card);
  cursor: pointer;
}

.hamburgerLines,
.hamburgerLines::before,
.hamburgerLines::after {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--vt-on-deep);
  border-radius: 2px;
  transition: all 0.3s var(--ease-out);
  position: relative;
}

.hamburgerLines::before,
.hamburgerLines::after {
  content: '';
  position: absolute;
}

.hamburgerLines::before {
  top: -7px;
}

.hamburgerLines::after {
  top: 7px;
}

.navToggle:checked ~ .hamburger .hamburgerLines {
  background: transparent;
}

.navToggle:checked ~ .hamburger .hamburgerLines::before {
  top: 0;
  transform: rotate(45deg);
}

.navToggle:checked ~ .hamburger .hamburgerLines::after {
  top: 0;
  transform: rotate(-45deg);
}

/* Sidebar overlay */
.sidebarOverlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(61, 64, 91, 0.5);
  z-index: 999;
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}

.navToggle:checked ~ .sidebarOverlay {
  display: block;
  opacity: 1;
  pointer-events: auto;
}

/* Sidebar */
.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  width: var(--sidebar-width);
  height: 100vh;
  background: var(--vt-ink);
  color: var(--vt-on-deep);
  display: flex;
  flex-direction: column;
  z-index: 1000;
  overflow-y: auto;
  transition: transform 0.4s var(--ease-out);
}

.sidebarBrand {
  padding: 2rem 1.5rem 1.5rem;
  border-bottom: 1px solid rgba(244, 241, 222, 0.1);
}

.sidebarNav {
  flex: 1;
  padding: 1.5rem 0;
}

.sidebarNav ul {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.navLink {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1.5rem;
  font-size: 0.9rem;
  font-weight: 500;
  color: rgba(244, 241, 222, 0.65);
  transition: all 0.3s var(--ease-out);
  position: relative;
}

.navLink::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%) scaleY(0);
  width: 3px;
  height: 70%;
  background: var(--vt-accent);
  border-radius: 0 3px 3px 0;
  transition: transform 0.3s var(--ease-out);
}

.navLink:hover,
.navLink:focus-visible {
  color: var(--vt-on-deep);
  background: rgba(244, 241, 222, 0.06);
}

.navLink:hover::before,
.navLink:focus-visible::before {
  transform: translateY(-50%) scaleY(1);
}

.navIcon {
  width: 20px;
  text-align: center;
  font-size: 1.1rem;
  flex-shrink: 0;
}

.sidebarFooter {
  padding: 1.5rem;
  border-top: 1px solid rgba(244, 241, 222, 0.1);
}

.sidebarHours {
  font-size: 0.78rem;
  color: rgba(244, 241, 222, 0.5);
  line-height: 1.6;
}

.sidebarHours strong {
  color: var(--vt-accent-on-deep);
  font-weight: 600;
}

/* Main */
.main {
  margin-left: var(--sidebar-width);
  min-height: 100vh;
}

/* Hero */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: var(--section-pad);
  background:
    radial-gradient(ellipse at 20% 80%, rgba(129, 178, 154, 0.15) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 20%, rgba(196, 90, 58, 0.12) 0%, transparent 50%),
    var(--vt-surface);
  overflow: hidden;
}

.heroContent {
  max-width: 640px;
  position: relative;
  z-index: 2;
}

.heroBadge {
  display: inline-block;
  padding: 0.4rem 1rem;
  background: var(--sage);
  color: var(--vt-on-accent);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border-radius: 50px;
  margin-bottom: 1.5rem;
}

.heroTitle {
  font-size: clamp(2.8rem, 6vw, 4.5rem);
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 0.5rem;
  letter-spacing: -0.03em;
}

.heroSubtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--vt-ink-soft);
  margin-bottom: 2rem;
  max-width: 480px;
}

.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.heroDeco {
  position: absolute;
  right: -2%;
  top: 50%;
  transform: translateY(-50%);
  width: clamp(280px, 35vw, 500px);
  height: clamp(280px, 35vw, 500px);
  z-index: 1;
}

.scoop {
  position: absolute;
  border-radius: 50%;
  box-shadow: inset 0 -10px 30px rgba(0, 0, 0, 0.08), 0 6px 20px rgba(0, 0, 0, 0.06);
}

.scoopStrawberry {
  width: 60%;
  height: 60%;
  background: radial-gradient(circle at 35% 35%, var(--terracotta-light), var(--vt-accent));
  top: 0;
  right: 10%;
}

.scoopMint {
  width: 50%;
  height: 50%;
  background: radial-gradient(circle at 35% 35%, var(--sage-light), var(--sage-dark));
  bottom: 8%;
  right: 0;
}

.scoopVanilla {
  width: 45%;
  height: 45%;
  background: radial-gradient(circle at 35% 35%, var(--vt-surface-2), var(--cream-dark));
  bottom: 15%;
  left: 5%;
}

.scoopHighlight {
  position: absolute;
  width: 25%;
  height: 25%;
  background: rgba(255, 255, 255, 0.5);
  border-radius: 50%;
  top: 15%;
  left: 20%;
  filter: blur(6px);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.85rem 1.75rem;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: all 0.3s var(--ease-out);
}

.btnPrimary {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.btnPrimary:hover,
.btnPrimary:focus-visible {
  background: var(--terracotta-dark);
  transform: translateY(-2px);
  box-shadow: 0 6px 24px rgba(196, 90, 58, 0.35);
}

.btnOutline {
  border: 2px solid var(--vt-ink);
  color: var(--vt-ink);
  background: transparent;
}

.btnOutline:hover,
.btnOutline:focus-visible {
  background: var(--vt-ink);
  color: var(--vt-on-deep);
  transform: translateY(-2px);
}

/* Section base */
.section {
  padding: var(--section-pad);
}

.sectionAlt {
  background: var(--vt-surface-2);
}

.sectionHeader {
  margin-bottom: clamp(2rem, 4vw, 3.5rem);
}

.sectionLabel {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--vt-accent-ink);
  margin-bottom: 0.75rem;
}

.sectionTitle {
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  color: var(--vt-ink);
  letter-spacing: -0.02em;
}

.sectionDesc {
  margin-top: 0.75rem;
  font-size: 1.05rem;
  color: var(--vt-ink-soft);
  max-width: 560px;
}

/* Services marquee */
.flavorsSection {
  overflow: hidden;
  padding-left: 0;
  padding-right: 0;
}

.flavorsSection .sectionHeader {
  padding-left: var(--section-pad);
  padding-right: var(--section-pad);
}

.marquee {
  position: relative;
  width: 100%;
  overflow: hidden;
  padding: 1rem 0 2rem;
}

.marquee::before,
.marquee::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  width: 80px;
  z-index: 2;
  pointer-events: none;
}

.marquee::before {
  left: 0;
  background: linear-gradient(to right, var(--vt-surface-2), transparent);
}

.marquee::after {
  right: 0;
  background: linear-gradient(to left, var(--vt-surface-2), transparent);
}

.marqueeTrack {
  display: flex;
  width: max-content;
  gap: 1.25rem;
  animation: marquee-scroll 35s linear infinite;
}

.marqueeTrackReverse {
  animation-name: marquee-scroll-reverse;
  animation-duration: 40s;
  margin-top: 1.25rem;
}

.marquee:hover .marqueeTrack {
  animation-play-state: paused;
}

@keyframes marquee-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes marquee-scroll-reverse {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

.flavorCard {
  flex-shrink: 0;
  width: 340px;
  background: var(--vt-surface-2);
  border-radius: var(--radius-lg);
  padding: 1.4rem 1.5rem;
  box-shadow: var(--shadow-card);
  display: flex;
  align-items: center;
  gap: 1.15rem;
  transition: all 0.35s var(--ease-out);
  position: relative;
  overflow: hidden;
  cursor: default;
}

.flavorCard:hover {
  box-shadow: var(--shadow-hover);
  transform: scale(1.03);
}

.flavorCardSwatch {
  width: 62px;
  height: 62px;
  border-radius: 50%;
  flex-shrink: 0;
  position: relative;
  box-shadow: inset 0 -4px 10px rgba(0, 0, 0, 0.08);
}

.flavorCardSwatch::after {
  content: '';
  position: absolute;
  width: 35%;
  height: 35%;
  background: rgba(255, 255, 255, 0.45);
  border-radius: 50%;
  top: 12%;
  left: 18%;
  filter: blur(3px);
}

.flavorCardInfo {
  min-width: 0;
}

.flavorCardName {
  font-family: var(--font-heading);
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 0.15rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.flavorCardType {
  font-size: 0.68rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--sage);
  margin-bottom: 0.3rem;
}

.flavorCardDesc {
  font-size: 0.82rem;
  color: var(--vt-ink-soft);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Swatch variants using spine/extended colors */
.swatch1 { background: radial-gradient(circle at 35% 35%, #fce4b8, #e6c68a); }
.swatch2 { background: radial-gradient(circle at 35% 35%, #6b3a2a, #3e2118); }
.swatch3 { background: radial-gradient(circle at 35% 35%, var(--sage-light), var(--sage-dark)); }
.swatch4 { background: radial-gradient(circle at 35% 35%, #c9b3d6, #9b7eb8); }
.swatch5 { background: radial-gradient(circle at 35% 35%, #a8d8ea, #6bb7d4); }
.swatch6 { background: radial-gradient(circle at 35% 35%, #d4a76a, #b8863e); }

/* About */
.aboutContent {
  max-width: 700px;
}

.aboutParagraph {
  font-size: 1rem;
  color: var(--vt-ink-soft);
  margin-bottom: 1.25rem;
}

/* Footer */
.footer {
  padding: 3rem var(--section-pad) 2rem;
  background: var(--vt-ink);
  color: rgba(244, 241, 222, 0.6);
}

.footerTop {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid rgba(244, 241, 222, 0.1);
}

.footerLinks {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem 4rem;
}

.footerCol {
  min-width: 140px;
}

.footerCol h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--vt-accent-on-deep);
  margin-bottom: 0.75rem;
}

.footerCol ul {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.footerCol a {
  font-size: 0.88rem;
  transition: color 0.2s ease;
}

.footerCol a:hover,
.footerCol a:focus-visible {
  color: var(--vt-on-deep);
}

.footerBottom {
  padding-top: 1.5rem;
  font-size: 0.78rem;
  text-align: center;
}

/* Focus visible defaults */
.root a:focus-visible,
.root button:focus-visible,
.root input:focus-visible,
.root label:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  .root *,
  .root *::before,
  .root *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Tablet */
@media (max-width: 1024px) {
  .root {
    --sidebar-width: 0px;
  }

  .sidebar {
    transform: translateX(-100%);
    width: 280px;
  }

  .navToggle:checked ~ .sidebar {
    transform: translateX(0);
  }

  .hamburger {
    display: flex;
  }

  .main {
    margin-left: 0;
  }

  .heroDeco {
    opacity: 0.3;
    right: -10%;
  }

  .section {
    padding-left: 2rem;
    padding-right: 2rem;
  }
}

/* Mobile */
@media (max-width: 640px) {
  .hero {
    padding-top: 5rem;
    min-height: auto;
  }

  .heroDeco {
    opacity: 0.2;
    right: -15%;
    width: 220px;
    height: 220px;
  }

  .section {
    padding-left: 1.25rem;
    padding-right: 1.25rem;
  }

  .marquee::before,
  .marquee::after {
    width: 40px;
  }

  .flavorCard {
    width: 280px;
  }

  .footerTop {
    flex-direction: column;
  }

  .footerLinks {
    gap: 2rem;
  }
}
